const cfg = $('Config').first().json;
const c = $json;
const base = "You extract structured product data from part of a supplier's information document (info.md). The text is messy: plain text, emoji bullets, typos, price lists, delivery lists.\nRULES\n1. A product is something a customer can buy, named by a title, heading or price-list heading. Section headers (Price, Sizes, Colours, Fabric, Delivery, Notes), option lists, surcharges, sizes and delivery areas are NEVER products.\n2. Each product needs source_excerpt: ONE line (max 80 chars) copied exactly from the text. Never invent products, names, prices or areas.\n3. identity_source = 'explicit_title' only if the name is written in the text as a title/heading. If you had to describe it yourself use 'inferred', confidence <= 0.5, needs_review true. A finish or colour alone ('Matt finishing') is not a product name.\n4. Every price line becomes its own prices[] entry: amount as a plain number, currency from the symbol, raw_text = the original line copied exactly. Sizes/styles go in variants and the price's variant field. Frame/set/fitting splits: keep one entry per amount and say which in kind.\n5. Optional extras go in options (is_included=false). Dimensions and materials go in specifications or facts.\n6. Delivery areas, schedules, charges and payment terms go in fulfilment_terms. areas MUST be objects like {\"name\":\"Sheffield\",\"postcode\":\"S\"}; never return empty objects; one area per list line. Do not invent payment terms.\n7. Anything you cannot classify goes into unclassified_content with a reason. Never drop information.\n8. Answer ONLY by calling record_extraction.\n\nEXAMPLE\nText: 'Oak Table\\nSize: Price:\\n4ft  £120\\nDelivery: Leeds - LS'\nOutput: {\"products\":[{\"name\":\"Oak Table\",\"identity_source\":\"explicit_title\",\"confidence\":0.9,\"source_excerpt\":\"Oak Table\",\"variants\":[{\"name\":\"4ft\"}],\"prices\":[{\"kind\":\"size_price\",\"label\":\"4ft\",\"variant\":\"4ft\",\"amount\":120,\"currency\":\"GBP\",\"raw_text\":\"4ft  £120\"}]}],\"fulfilment_terms\":[{\"term_type\":\"delivery\",\"label\":\"delivery\",\"areas\":[{\"name\":\"Leeds\",\"postcode\":\"LS\"}],\"raw_terms\":\"Delivery: Leeds - LS\"}],\"unclassified_content\":[],\"warnings\":[],\"overall_confidence\":0.9}";
const part = c.kind === 'delivery'
  ? "\nTHIS PART contains delivery/payment terms. Put them in fulfilment_terms (one term per zone or list, with schedule notes in schedules/conditions). Return products: [] unless a product is clearly defined here."
  : "\nTHIS PART contains product information. Extract products with their variants, prices, options and facts. Do not return fulfilment_terms unless delivery/payment text appears in this part.";
const system = base + part + "\nThis is part " + c.chunk_index + " of " + c.chunk_count + " of the same document; extract only what is in this part.";
const user = 'File: ' + c.source_filename + (c.chunk_index > 1 ? '\nDocument begins: ' + c.context : '') + '\n\n<document_part>\n' + c.text + '\n</document_part>';
const S = {type:'string'}, O = {type:'object'};
const schema = {type:'object', required:['products'], properties:{
  products:{type:'array', items:{type:'object', required:['name','source_excerpt','confidence'], properties:{
    name:S, identity_source:{type:'string', enum:['explicit_title','inferred']}, description:S, category:S, confidence:{type:'number'}, needs_review:{type:'boolean'}, notes:S, source_excerpt:S, specifications:O,
    variants:{type:'array', items:{type:'object', required:['name'], properties:{name:S, configuration:S, attributes:O, source_label:S, sort_order:{type:'integer'}}}},
    prices:{type:'array', items:{type:'object', required:['raw_text'], properties:{kind:S, label:S, variant:S, amount:{type:['number','null']}, currency:S, unit:S, applies_to:S, components:O, conditions:O, raw_text:S, confidence:{type:'number'}, needs_review:{type:'boolean'}}}},
    options:{type:'array', items:{type:'object', required:['name'], properties:{name:S, group:S, type:S, description:S, is_included:{type:'boolean'}, attributes:O, source_excerpt:S}}},
    facts:{type:'array', items:{type:'object', required:['key'], properties:{group:S, key:S, value:S, unit:S, raw_text:S}}}}}},
  fulfilment_terms:{type:'array', items:{type:'object', properties:{term_type:{type:'string', enum:['delivery','payment','charges','returns','other']}, label:S,
    areas:{type:'array', items:{type:'object', required:['name'], properties:{name:S, postcode:S}}}, schedules:O, charges:{type:'array', items:O}, payment_methods:{type:'array', items:O}, conditions:O, raw_terms:S}}},
  unclassified_content:{type:'array', items:{type:'object', properties:{type:S, text:S, reason:S}}}, warnings:{type:'array', items:S}, overall_confidence:{type:'number'}}};
const request = {
  model: cfg.model_id || 'nvidia/nemotron-3-ultra-550b-a55b:free',
  max_tokens: Number(cfg.max_tokens) || 8000,
  messages: [{ role:'system', content: system }, { role:'user', content: user }],
  tools: [{ type:'function', function:{ name:'record_extraction', description:'Record the structured extraction of this document part.', parameters: schema } }],
  tool_choice: { type:'function', function:{ name:'record_extraction' } }
};
return { json: { request, run_id: c.run_id, source_document_id: c.source_document_id, chunk_index: c.chunk_index, chunk_count: c.chunk_count, kind: c.kind } };

const resp = $json;
const c = $('Build LLM Request').item.json;
const base = { run_id: c.run_id, chunk_index: c.chunk_index, chunk_count: c.chunk_count, kind: c.kind };
const num = v => { if (typeof v === 'number') return Number.isFinite(v) ? v : null; if (typeof v === 'string') { const n = parseFloat(v.replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : null; } return null; };
const clamp = v => { const n = num(v); return n === null ? 0 : Math.min(1, Math.max(0, n)); };
const lenient = s => { try { return JSON.parse(s); } catch (e) { const a = s.indexOf('{'), b = s.lastIndexOf('}'); if (a >= 0 && b > a) return JSON.parse(s.slice(a, b + 1).replace(/,\s*([}\]])/g, '$1')); throw e; } };
try {
  if (resp.error) throw new Error('LLM request failed: ' + (resp.error.message || JSON.stringify(resp.error)).slice(0, 300));
  const choice = resp.choices && resp.choices[0];
  if (!choice || !choice.message) throw new Error('LLM returned no message');
  if (choice.finish_reason === 'length') throw new Error('LLM output truncated (max_tokens); lower chunk_max_chars or raise max_tokens');
  const m = choice.message; let p;
  const tc = (m.tool_calls || []).find(x => x.function && x.function.name === 'record_extraction');
  if (tc) p = lenient(tc.function.arguments);
  else if (m.content) p = lenient(String(m.content).trim());
  else throw new Error('LLM response is empty');
  if (!p || typeof p !== 'object') throw new Error('payload is not an object');
  p.products = (Array.isArray(p.products) ? p.products : []).filter(x => x && typeof x.name === 'string' && x.name.trim()).map(x => {
    x.confidence = clamp(x.confidence);
    if (typeof x.source_excerpt === 'string') x.source_excerpt = x.source_excerpt.split('\n')[0].slice(0, 160);
    x.prices = (x.prices || []).map(pr => { const a = num(pr.amount); return { ...pr, amount: a, needs_review: !!pr.needs_review || a === null }; });
    return x;
  });
  p.fulfilment_terms = (Array.isArray(p.fulfilment_terms) ? p.fulfilment_terms : []).map(t => ({ ...t,
    areas: (Array.isArray(t.areas) ? t.areas : []).map(a => typeof a === 'string' ? { name: a.trim() } : a).filter(a => a && ((a.name && String(a.name).trim()) || a.postcode)) }));
  p.unclassified_content = Array.isArray(p.unclassified_content) ? p.unclassified_content : [];
  p.warnings = Array.isArray(p.warnings) ? p.warnings : [];
  p.overall_confidence = clamp(p.overall_confidence);
  p.warnings.push('chunk ' + c.chunk_index + '/' + c.chunk_count + ' model=' + (resp.model || 'unknown') + ' tokens=' + ((resp.usage && resp.usage.total_tokens) || '?'));
  return { json: { ...base, ok: true, payload: p } };
} catch (e) {
  return { json: { ...base, ok: false, error: String(e.message || e).slice(0, 500) } };
}

const out = { applied: 0, failed: 0, skipped_already_done: 0, by_status: {} };
const safe = n => { try { return $(n).all(); } catch (e) { return []; } };
for (const i of safe('Apply Extraction')) { out.applied++; const s = i.json.status || 'unknown'; out.by_status[s] = (out.by_status[s] || 0) + 1; }
out.failed = safe('Record Failure').length;
out.skipped_already_done = safe('Skip (already done)').length;
return [{ json: out }];

const cfg = $('Config').first().json;
const run = $('Begin Run').last().json;
const doc = $input.first().json;
const MAX = Number(cfg.chunk_max_chars) || 1800;
const text = String(doc.raw_content || '').replace(/\r/g, '');
if (!text.trim()) throw new Error('source document is empty');

const plain = l => l.replace(/[*_`#>]/g, '').replace(/[\u{1F000}-\u{1FFFF}\u2600-\u27BF\uFE0F\u200D]/gu, '').trim();
const isSep = l => /^\s*[*_=~\-]{6,}\s*$/.test(l);
const isAreaLine = l => /^[A-Za-z .'\/&-]{2,40}\.?\s*[-–]\s*[A-Za-z]{1,3}\.?(\s*[-–]\s*[A-Za-z]{1,3})?\.?\s*$/.test(plain(l));
const isHeading = l => {
  const t = plain(l); if (!t || t.length > 60) return false;
  const letters = t.replace(/[^A-Za-z]/g, '');
  return /:-?$/.test(t) || (letters.length >= 4 && t === t.toUpperCase()) || /\bareas?$/i.test(t) || /\b(routes|sides)\b/i.test(t) || /^\d+\.\s/.test(t);
};
const kindOf = lines => {
  const body = lines.filter(l => plain(l));
  if (!body.length) return 'product';
  if (/^(delivery|deliveries)\b/i.test(plain(body[0]))) return 'delivery';
  return body.filter(isAreaLine).length / body.length >= 0.4 ? 'delivery' : 'product';
};

// 1. split on separator lines
let sections = [], cur = [];
for (const l of text.split('\n')) { if (isSep(l)) { if (cur.length) sections.push(cur); cur = []; } else cur.push(l); }
if (cur.length) sections.push(cur);

// 2. oversized sections: split at headings, carry tiny heading-only pieces forward, then hard-split by lines
const size = ls => ls.join('\n').length;
const splitBig = ls => {
  if (size(ls) <= MAX) return [ls];
  let parts = [], c = [];
  for (const l of ls) { if (isHeading(l) && c.some(x => plain(x))) { parts.push(c); c = []; } c.push(l); }
  if (c.length) parts.push(c);
  const merged = []; let carry = [];
  for (const p of parts) { const q = carry.concat(p); if (size(p) < 150) carry = q; else { merged.push(q); carry = []; } }
  if (carry.length) { if (merged.length) merged[merged.length - 1] = merged[merged.length - 1].concat(carry); else merged.push(carry); }
  const out = [];
  for (const m of merged) { let b = []; for (const l of m) { if (size(b.concat(l)) > MAX && b.length) { out.push(b); b = []; } b.push(l); } if (b.length) out.push(b); }
  return out;
};
let units = [];
for (const s of sections) for (const u of splitBig(s)) if (u.some(x => plain(x))) units.push({ lines: u, kind: kindOf(u) });

// 3. pack neighbours of the same kind up to MAX
const chunks = [];
for (const u of units) {
  const last = chunks[chunks.length - 1];
  if (last && last.kind === u.kind && size(last.lines.concat(u.lines)) + 2 <= MAX) last.lines = last.lines.concat([''], u.lines);
  else chunks.push({ kind: u.kind, lines: u.lines.slice() });
}
const context = text.split('\n').map(plain).filter(Boolean).slice(0, 3).join(' | ').slice(0, 200);
return chunks.map((c, i) => ({ json: {
  run_id: run.run_id, source_document_id: doc.id, source_filename: doc.source_filename || 'info.md',
  chunk_index: i + 1, chunk_count: chunks.length, kind: c.kind, text: c.lines.join('\n').trim(), context
} }));

const items = $input.all().map(i => i.json);
const runId = items[0] && items[0].run_id ? items[0].run_id : $('Begin Run').last().json.run_id;
const ok = items.filter(i => i.ok), bad = items.filter(i => !i.ok);
if (!ok.length) throw new Error('all ' + items.length + ' chunks failed: ' + bad.map(b => 'part ' + b.chunk_index + ': ' + b.error).join(' | ').slice(0, 1500));
const nk = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const pm = new Map();
const addUnique = (arr, add, keyFn) => { const seen = new Set(arr.map(keyFn)); for (const x of add || []) { const k = keyFn(x); if (!seen.has(k)) { seen.add(k); arr.push(x); } } };
for (const r of ok.sort((a, b) => a.chunk_index - b.chunk_index)) for (const p of r.payload.products) {
  const k = nk(p.name); let t = pm.get(k);
  if (!t) { t = { ...p, variants: [], prices: [], options: [], facts: [] }; pm.set(k, t); }
  else { t.confidence = Math.min(t.confidence, p.confidence); t.description = t.description || p.description; t.specifications = { ...(p.specifications || {}), ...(t.specifications || {}) }; if (p.identity_source === 'explicit_title') t.identity_source = 'explicit_title'; t.needs_review = !!(t.needs_review && p.needs_review); }
  addUnique(t.variants, p.variants, v => nk(v.name) + '|' + nk(v.configuration));
  addUnique(t.prices, p.prices, x => [x.kind, x.label, x.variant, x.applies_to, x.raw_text].map(nk).join('|'));
  addUnique(t.options, p.options, o => nk(o.group) + '|' + nk(o.name));
  addUnique(t.facts, p.facts, f => nk(f.group) + '|' + nk(f.key));
}
const tm = new Map();
for (const r of ok) for (const t of r.payload.fulfilment_terms) {
  const k = nk(t.term_type || 'delivery') + '|' + nk(t.label); let m = tm.get(k);
  if (!m) { m = { ...t, areas: [], charges: [], payment_methods: [] }; tm.set(k, m); }
  else { m.schedules = { ...(t.schedules || {}), ...(m.schedules || {}) }; m.conditions = { ...(t.conditions || {}), ...(m.conditions || {}) }; m.raw_terms = [m.raw_terms, t.raw_terms].filter(Boolean).join('\n'); }
  addUnique(m.areas, t.areas, a => nk(a.name) + '|' + nk(a.postcode));
  addUnique(m.charges, t.charges, c => JSON.stringify(c));
  addUnique(m.payment_methods, t.payment_methods, c => JSON.stringify(c));
}
const warnings = ok.flatMap(r => r.payload.warnings).concat(bad.map(b => 'chunk ' + b.chunk_index + '/' + b.chunk_count + ' FAILED: ' + b.error));
const conf = ok.map(r => r.payload.overall_confidence);
const payload = {
  products: [...pm.values()], fulfilment_terms: [...tm.values()], unclassified_content: ok.flatMap(r => r.payload.unclassified_content), warnings,
  overall_confidence: conf.length ? Math.min(...conf) : 0, chunks_total: items.length, chunks_failed: bad.length
};
return [{ json: { run_id: runId, payload } }];
